begin;

create table public."Dim_Labor_Final" (
  "Id_Lab_Fin" bigint generated by default as identity primary key,
  "DESCRIPCION" character varying not null,
  "Id_Grupo_Labor" bigint not null references public."Dim_GrupoLabor" ("Id_Grupo_Labor") on update cascade on delete restrict,
  "id_Tipo_Jornal" smallint not null,
  estado smallint not null default 1 check (estado in (0, 1)),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public."Dim_Labor_Final" is
  'Catálogo maestro de labores finales vinculado a grupo de labor.';
comment on column public."Dim_Labor_Final"."id_Tipo_Jornal" is
  'Código de tipo de jornal; queda sin FK porque el catálogo de tipo de jornal aún no existe.';
comment on column public."Dim_Labor_Final".estado is
  'Estado del registro: 1 activo, 0 inactivo.';

alter table public."Dim_Labor_Final" enable row level security;
revoke all on table public."Dim_Labor_Final" from public, anon, authenticated;
grant select, insert, update, delete on table public."Dim_Labor_Final" to authenticated;

create policy dim_labor_final_select_admin on public."Dim_Labor_Final"
for select to authenticated using ((select private.is_admin()));
create policy dim_labor_final_insert_admin on public."Dim_Labor_Final"
for insert to authenticated with check ((select private.is_admin()));
create policy dim_labor_final_update_admin on public."Dim_Labor_Final"
for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy dim_labor_final_delete_admin on public."Dim_Labor_Final"
for delete to authenticated using ((select private.is_admin()));

create or replace function private.set_dim_labor_final_updated_at()
returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function private.set_dim_labor_final_updated_at() from public, anon, authenticated, service_role;

create trigger trg_dim_labor_final_updated_at
before update on public."Dim_Labor_Final"
for each row execute function private.set_dim_labor_final_updated_at();


select setval(
  pg_get_serial_sequence('public."Dim_Labor_Final"', 'Id_Lab_Fin'),
  (select max("Id_Lab_Fin") from public."Dim_Labor_Final"),
  true
);

do $$
declare
  v_sequence regclass := pg_get_serial_sequence('public."Dim_Labor_Final"', 'Id_Lab_Fin');
begin
  execute format('grant usage, select on sequence %s to authenticated', v_sequence);
end;
$$;

commit;
